import sys, os, json, platform, time, random
from pathlib import Path

START = time.time()

# Optional deps
try:
    import numpy as np
except Exception:
    np = None

# Import shared seed tools
seed_tools_ok = True
try:
    sys.path.append('storage/shared')
    from utilities.seed_tools import set_seed, make_rng, seed_from_str, mix_seed
except Exception as e:
    seed_tools_ok = False
    # Fallback simple seed helpers
    def _to_u32(x: int) -> int: return x & 0xFFFFFFFF
    def set_seed(seed: int) -> int:
        s = _to_u32(int(seed))
        os.environ['PYTHONHASHSEED'] = str(s)
        random.seed(s)
        if np is not None:
            try:
                np.random.seed(s)
            except Exception:
                pass
        return s
    def make_rng(seed: int):
        s = set_seed(seed)
        py_rng = random.Random(s)
        if np is not None:
            if hasattr(np.random, "default_rng"):
                np_rng = np.random.default_rng(s)
            else:
                class _Legacy:
                    def __init__(self, seed): self.rs = np.random.RandomState(seed)
                    def random(self, n): return self.rs.rand(n)
                np_rng = _Legacy(s)
        else:
            np_rng = None
        return np_rng, py_rng
    def seed_from_str(s: str) -> int:
        try:
            import hashlib
            h = hashlib.sha256(s.encode('utf-8')).hexdigest()
            return int(h[:8], 16)
        except Exception:
            return sum(ord(c) for c in s) & 0xFFFFFFFF
    def mix_seed(seed: int, salt: int) -> int:
        GOLD = 0x9E3779B9
        return _to_u32(_to_u32(seed) ^ (_to_u32(salt) + GOLD))

def env_info():
    info = {
        "python": platform.python_version(),
        "platform": platform.platform(),
        "implementation": platform.python_implementation(),
        "seed_tools_imported": seed_tools_ok,
    }
    for name in ["numpy", "scipy", "pandas"]:
        try:
            mod = __import__(name)
            info[name] = getattr(mod, "__version__", "unknown")
        except Exception:
            info[name] = None
    return info

def np_sample(seed: int, n=5):
    if np is None:
        return None, None
    s = set_seed(seed)
    # Legacy global generator
    legacy = np.random.random(n)
    # Independent generator
    if hasattr(np.random, "default_rng"):
        rng = np.random.default_rng(s)
        new = rng.random(n)
    else:
        rs = np.random.RandomState(s)
        new = rs.rand(n)
    return legacy, new

def py_sample(seed: int, n=5):
    s = set_seed(seed)
    rng = random.Random(s)
    return [random.random() for _ in range(n)], [rng.random() for _ in range(n)]

def allclose(a, b, tol=1e-12):
    if a is None or b is None:
        return a is b
    if np is not None:
        return np.allclose(a, b, atol=tol, rtol=0)
    # Fallback elementwise
    if len(a) != len(b):
        return False
    return all(abs(x - y) <= tol for x, y in zip(a, b))

# Determinism checks
base_seed = 123456789
seed_hash = seed_from_str("Station")

# Python random
py_a_global, py_a_inst = py_sample(base_seed, 8)
py_b_global, py_b_inst = py_sample(base_seed, 8)
py_same = (py_a_global == py_b_global) and (py_a_inst == py_b_inst)

py_c_global, py_c_inst = py_sample(mix_seed(base_seed, 1), 8)
py_diff = (py_a_global != py_c_global) or (py_a_inst != py_c_inst)

# NumPy random (if available)
if np is not None:
    np_a_legacy, np_a_new = np_sample(base_seed, 8)
    np_b_legacy, np_b_new = np_sample(base_seed, 8)
    np_same_legacy = allclose(np_a_legacy, np_b_legacy)
    np_same_new = allclose(np_a_new, np_b_new)

    np_c_legacy, np_c_new = np_sample(mix_seed(base_seed, 1), 8)
    np_diff_legacy = not allclose(np_a_legacy, np_c_legacy)
    np_diff_new = not allclose(np_a_new, np_c_new)
else:
    np_a_legacy = np_a_new = None
    np_same_legacy = np_same_new = None
    np_diff_legacy = np_diff_new = None

# File I/O test
probes_dir = Path("storage/shared/probes")
probes_dir.mkdir(parents=True, exist_ok=True)

summary_path = probes_dir / "axiom_env_probe.json"
array_path = probes_dir / "axiom_array.npy"

io_ok = True
io_msg = "ok"
try:
    result_array = None
    if np is not None and np_a_new is not None:
        result_array = np.asarray(np_a_new, dtype=float)
        np.save(array_path, result_array)
        loaded = np.load(array_path)
        io_ok = io_ok and np.allclose(result_array, loaded)
    else:
        # Write a tiny json-only artifact if numpy unavailable
        with open(probes_dir / "axiom_text_artifact.txt", "w", encoding="utf-8") as f:
            f.write("numpy not available; wrote text artifact instead.\n")
except Exception as e:
    io_ok = False
    io_msg = f"Exception during npy IO: {e}"

report = {
    "env": env_info(),
    "seed_from_str_demo": seed_hash,
    "determinism": {
        "python_random_same_seed": py_same,
        "python_random_diff_seed": py_diff,
        "numpy_same_seed_legacy": np_same_legacy,
        "numpy_same_seed_new": np_same_new,
        "numpy_diff_seed_legacy": np_diff_legacy,
        "numpy_diff_seed_new": np_diff_new,
    },
    "artifacts": {
        "summary_path": str(summary_path),
        "array_path": str(array_path) if np is not None else None,
    },
    "io_ok": io_ok,
    "io_msg": io_msg,
    "seed_tools_imported": seed_tools_ok,
}

with open(summary_path, "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=True)

END = time.time()
report["timing_sec"] = round(END - START, 6)

print("=== Station Environment Probe ===")
print(json.dumps(report, indent=2, sort_keys=True))
print("Probe complete.")
